        { id = "new_member_intro", t = { "e.join" }, c = {}, cd = 120, roles = 2, l = { { 1, "welcome to the ls! make yourself at home", "Welcome to the Linkshell! Make yourself at home." }, { 2, "if you've got questions about jobs or missions or finding a pt, just ask", "If you have questions about jobs, missions, or finding a group, feel free to ask." } } },
        { id = "party_forms", t = { "e.lfp" }, c = {}, cd = 30, roles = 3, l = { { 1, "got a pt coming together, what jobs can everyone bring?", "We have a group taking shape. What jobs can everyone bring?" }, { 2, "I can ask around and see who's free", "I can ask around and see who is free." }, { 3, "I can come once I'm done in town", "I can come after I finish in town." }, { 1, "ok cool, we'll pick the camp once we know the lineup", "Good. We will settle the camp once we know the lineup." } } },
        { id = "party_wipe", t = { "e.wipe" }, c = {}, cd = 60, roles = 3, l = { { 1, "ok let's regroup and figure out what went wrong before we try again", "Let's regroup and work out what went wrong before we try again." }, { 2, "I vote we don't stand in that exact spot next time", "I vote we avoid standing in that exact spot next time." }, { 3, "I'll wait here, take your time", "I will wait here. Take your time." } } },
        { id = "crafting_chat", t = { "e.craft" }, c = {}, cd = 90, roles = 3, l = { { 1, "trying to get a few more skillups before I quit for tonight", "I am trying to get a few more skill-ups before I pack it in." }, { 2, "got any tips for picking recipes at my level?", "Do you have any advice for choosing recipes at my level?" }, { 3, "check the recipe range and mat costs first, a little planning saves a lot of gil", "Check the recipe range and material cost first. A little planning saves a lot of gil." } } },
        { id = "late_night_goodbye", t = { "e.logout" }, c = {}, cd = 60, roles = 3, l = { { 1, "gotta call it a night, early start tomorrow", "I need to call it a night. Early start tomorrow." }, { 2, "rest well, see you next time!", "Rest well. We will see you next time!" }, { 3, "night, take care", "Night. Take care." } } },
        { id = "zone_travel", t = { "ls" }, c = { "town" }, cd = 60, roles = 2, l = { { 1, "think I'll head out and see what the next area's like", "I think I will take the road out and see what the next region is like." }, { 2, "safe travels, let us know when you get there", "Travel safely. Let us know when you arrive." } } },
        { id = "friendly_rivalry", t = { "e.levelup" }, c = { "rival" }, cd = 90, roles = 2, l = { { 1, "I see someone's been busy. guess I gotta catch up", "I see you have been busy. I will have to catch up." }, { 2, "not everything has to be a competition lol", "Try not to turn every conversation into a competition." }, { 1, "no promises, keeps it interesting", "No promises. It keeps things interesting." } } },
