        { id = "party_aftercare", t = { "e.party_end" }, c = {}, cd = 90, roles = 3, l = { { 1, "good job everyone, take a sec to recover before you head out again", "Everyone did well. Take a moment to recover before heading out again." }, { 2, "camp was good once we got into a rhythm", "The camp was good once we settled into a rhythm." }, { 3, "ty for the pt", "Thanks for the group." } } },
        { id = "crafting_mentorship", t = { "ls" }, c = { "craft" }, cd = 90, roles = 2, l = { { 1, "I keep picking recipes that cost way more than I expected", "I keep choosing recipes that cost more than I expected." }, { 2, "check mat costs and the recipe range before you start. small batches while you're learning", "Check the material cost and recipe range before you start. Small batches are safer while learning." }, { 1, "makes sense, I'll do a few at a time", "That makes sense. I will try a few at a time." } } },
        { id = "scouting_uncertainty", t = { "ls" }, c = {}, cd = 90, roles = 3, l = { { 1, "heard a report but haven't confirmed anything yet", "I heard a report, but I have not confirmed anything yet." }, { 2, "then it's a rumor till someone checks", "Then let's call it a rumor until someone checks." }, { 3, "yeah, no need to send people across the map on a guess", "Good. No need to send people across the region on a guess." } } },
        { id = "late_quiet_chat", t = { "ls" }, c = { "night" }, cd = 90, roles = 3, l = { { 1, "so peaceful around town right now", "It is peaceful around town right now." }, { 2, "good time to sort gear", "A good time to sort equipment." }, { 3, "or just sit a while and watch the road", "Or just sit a while and watch the road." } } },
        { id = "linkshell_welcome_round", t = { "e.join" }, c = {}, cd = 90, roles = 3, l = { { 1, "everyone say hi to our new member!", "Let's give our new member a proper welcome." }, { 2, "if you need help finding your feet, ask in ls", "If you need help finding your feet, ask in the shell." }, { 3, "o/ welcome!", "Welcome!" } } },
        { id = "mission_helper_arc", t = { "ls" }, c = { "lowlevel" }, cd = 720, roles = 3, l = { { 1, "can someone help with my next mission? not sure what I need first", "Could someone help me with my next mission step? I am not sure what I need first." }, { 2, "sure, what step are you on? we'll check what you need", "Of course. Tell us the exact mission stage, and we will check the requirements." }, { 3, "I can come if the timing works", "I can come along if the timing works. Let us avoid guessing at the objective." }, { 1, "ty, I'll check my mission log first", "Thanks. I will check my mission log before we set a time." } } },
        { id = "camp_debate_resolution", t = { "ls" }, c = { "exp" }, cd = 240, roles = 3, l = { { 1, "I vote the farther camp, better exp and better stories", "I vote for the farther camp. Better challenge, better stories." }, { 2, "closer camp suits the pt we have better imo", "The nearer camp suits our current party better." }, { 3, "start close and decide after we see how it goes?", "Could we start nearby and decide after seeing how the group handles it?" }, { 2, "fair, we'll check after the first round", "That is fair. We will reassess after the first round." }, { 1, "deal. my grand expedition can wait", "Deal. I can save my grand expedition for another night." } } },
        { id = "event_postmortem_arc", t = { "e.win" }, c = {}, cd = 720, roles = 3, l = { { 1, "thanks for coming everyone! how'd it feel from your side?", "Thanks for coming, everyone. How did the plan feel from your side?" }, { 2, "meeting spot worked well, could've shared the supply list earlier though", "The meeting point worked well. We could have shared the supply list earlier." }, { 3, "agreed, good pace and nobody got left behind", "Agreed. The pace was good, and nobody was left behind." }, { 1, "I'll post the supply list earlier next time, ty", "I will include the supply list next time. Appreciate the feedback." } } },
        { id = "rumor_correction_arc", t = { "ls" }, c = {}, cd = 180, roles = 3, l = { { 1, "heard there's a new shortcut to the camp, is that true?", "I heard there is a new shortcut to the camp. Is that true?" }, { 2, "haven't checked it, I'd look it up before trusting it", "I have not verified it. Let's check a reliable source before recommending it." }, { 3, "till then let's stick to the way we know", "Until then, we should stick to the route we know." }, { 1, "fair enough", "Fair enough. I will mark it as unconfirmed." } } },
        { id = "quiet_evening_arc", t = { "ls" }, c = { "quiet" }, cd = 360, roles = 2, l = { { 1, "peaceful night. anyone have a little adventure planned?", "A peaceful night. Anyone have a small adventure planned?" }, { 2, "not tonight, happy just hanging in ls", "Not tonight. I am happy just listening to the Linkshell." }, { 1, "I'll keep it quiet then, enjoy :)", "Then I will keep the chatter gentle. Enjoy the quiet." } } },
        { id = "loot_rules_alignment", t = { "e.bcnm_start" }, c = {}, cd = 720, roles = 2, l = { { 1, "before we go, let's agree how drops get handled", "Before we go, let's agree how drops and treasure will be handled." }, { 2, "clear rules now saves awkward stuff later", "Clear rules now prevent awkward surprises later." }, { 1, "ok, I'll say the rules before the first pull", "Agreed. I will state the rules before the first pull." } } },
        { id = "returning_member_catchup", t = { "e.wb_long" }, c = {}, cd = 10080, roles = 2, l = { { 1, "wb! not much you need to catch up on all at once", "A few adventures and plenty of ordinary evenings. Nothing you need to catch up on all at once." }, { 2, "good to have you back, we can fill you in whenever", "Welcome back. We can fill you in when you have time." } } },
        { id = "friendship_reconnect", t = { "e.wb_long" }, c = {}, cd = 10080, roles = 2, l = { { 1, "been a while since we went out together", "It has been a while since we adventured together." }, { 2, "no need to explain the gap, we can pick up whenever", "It has. No need to explain the gap. We can pick up whenever it suits us." }, { 1, "a chill outing sometime soon would be nice", "I would like that. A relaxed outing sometime soon." } } },
    },
    npc = {
        { id = "npc_town_001_v1", cat = "npc_town", text = "Welcome, traveler. The road has been busy today." },
        { id = "npc_town_002_v1", cat = "npc_town", text = "Take care when you leave the safety of the city walls." },
        { id = "npc_town_003_v1", cat = "npc_town", text = "Adventurers come through here with the strangest stories." },
        { id = "npc_town_004_v1", cat = "npc_town", text = "The guild has been receiving requests for supplies all morning." },
        { id = "npc_town_005_v1", cat = "npc_town", text = "If you are traveling far, make sure you have what you need." },
        { id = "npc_town_006_v1", cat = "npc_town", text = "Visitors often underestimate how quickly the weather can change." },
        { id = "npc_town_007_v1", cat = "npc_town", text = "Please keep the main road clear for merchants and chocobos." },
        { id = "npc_town_008_v1", cat = "npc_town", text = "I have lived here many years, and there is always something new to see." },
        { id = "npc_town_009_v1", cat = "npc_town", text = "Some travelers hurry past without ever looking up at the rooftops." },
        { id = "npc_town_010_v1", cat = "npc_town", text = "May your journey bring you safely home." },
        { id = "npc_guild_001_v1", cat = "npc_guild", text = "Please check the guild's posted hours before returning tomorrow." },
        { id = "npc_guild_002_v1", cat = "npc_guild", text = "Materials are not always available in the quantities you expect." },
        { id = "npc_guild_003_v1", cat = "npc_guild", text = "A careful craftsperson wastes very little." },
        { id = "npc_guild_004_v1", cat = "npc_guild", text = "Do not rush the synthesis. Preparation matters." },
        { id = "npc_guild_005_v1", cat = "npc_guild", text = "If you are learning, start with a recipe suited to your current skill." },
        { id = "npc_guild_006_v1", cat = "npc_guild", text = "We appreciate customers who know exactly what they need." },
        { id = "npc_guild_007_v1", cat = "npc_guild", text = "Guild members have been busy with orders this week." },
        { id = "npc_guild_008_v1", cat = "npc_guild", text = "Keep your tools in good condition. It saves trouble later." },
        { id = "npc_guard_001_v1", cat = "npc_guard", text = "Stay alert beyond the gates. Not every traveler is friendly." },
        { id = "npc_guard_002_v1", cat = "npc_guard", text = "Report unusual activity to the guard stationed at the next post." },
        { id = "npc_guard_003_v1", cat = "npc_guard", text = "Keep the road clear and do not obstruct the gate." },
        { id = "npc_guard_004_v1", cat = "npc_guard", text = "Those heading into dangerous territory should travel prepared." },
        { id = "npc_guard_005_v1", cat = "npc_guard", text = "The patrol has already passed. The road is clear for now." },
        { id = "npc_guard_006_v1", cat = "npc_guard", text = "Please do not mistake a quiet road for a safe one." },
        { id = "npc_guard_007_v1", cat = "npc_guard", text = "We do what we can to keep the city peaceful." },
        { id = "exp2_npc_city_life_001", cat = "npc_city_life", text = "The market has been lively since the merchants arrived." },
        { id = "exp2_npc_city_life_002", cat = "npc_city_life", text = "Travelers have been asking for directions all morning." },
        { id = "exp2_npc_city_life_003", cat = "npc_city_life", text = "I hope the rain clears before the next caravan departs." },
        { id = "exp2_npc_city_life_004", cat = "npc_city_life", text = "Please mind the steps. They can be slippery after a shower." },
        { id = "exp2_npc_city_life_005", cat = "npc_city_life", text = "An adventurer left a parcel here. I hope they remember where they put it." },
        { id = "exp2_npc_city_life_006", cat = "npc_city_life", text = "The city sounds different when the airship has just arrived." },
        { id = "exp2_npc_city_life_007", cat = "npc_city_life", text = "We have had visitors from all three nations this week." },
        { id = "exp2_npc_city_life_008", cat = "npc_city_life", text = "Take a moment to rest before setting out again." },
        { id = "exp2_npc_city_life_009", cat = "npc_city_life", text = "The guild workers have been busy since sunrise." },
        { id = "exp2_npc_city_life_010", cat = "npc_city_life", text = "Somewhere nearby, someone is always looking for a missing chocobo." },
        { id = "exp2_npc_city_life_011", cat = "npc_city_life", text = "Please keep your weapons secured while inside the shop." },
        { id = "exp2_npc_city_life_012", cat = "npc_city_life", text = "I have heard plenty of stories from the road, though I suspect some are exaggerated." },
        { id = "exp2_npc_city_life_013", cat = "npc_city_life", text = "The guards have been changing shifts. The gate should be clear soon." },
        { id = "exp2_npc_city_life_014", cat = "npc_city_life", text = "Merchants prefer customers who know what they came to buy." },
        { id = "exp2_npc_city_life_015", cat = "npc_city_life", text = "I hope you find what you are looking for today." },
        { id = "exp2_npc_wilderness_001", cat = "npc_wilderness", text = "Keep to the path if you are unfamiliar with this region." },
        { id = "exp2_npc_wilderness_002", cat = "npc_wilderness", text = "The wind has been strong across the open ground today." },
        { id = "exp2_npc_wilderness_003", cat = "npc_wilderness", text = "Travelers often underestimate the distance between safe places." },
        { id = "exp2_npc_wilderness_004", cat = "npc_wilderness", text = "Do not follow strange lights into the brush after dark." },
        { id = "exp2_npc_wilderness_005", cat = "npc_wilderness", text = "If you hear a monster nearby, give it room and keep moving." },
        { id = "exp2_npc_wilderness_006", cat = "npc_wilderness", text = "Some gatherers come here before dawn to avoid the crowds." },
        { id = "exp2_npc_wilderness_007", cat = "npc_wilderness", text = "Please do not leave your rubbish along the road." },
        { id = "exp2_npc_wilderness_008", cat = "npc_wilderness", text = "The weather can turn quickly beyond the hills." },
        { id = "exp2_npc_wilderness_009", cat = "npc_wilderness", text = "I have seen many adventurers pass through, but few stop to enjoy the view." },
        { id = "exp2_npc_wilderness_010", cat = "npc_wilderness", text = "Take care near the cliffs. The ground is not as steady as it looks." },
        { id = "exp2_npc_wilderness_011", cat = "npc_wilderness", text = "That path is longer, but it is easier to follow." },
        { id = "exp2_npc_wilderness_012", cat = "npc_wilderness", text = "Wait for your companions before crossing the open field." },
        { id = "exp2_npc_wilderness_013", cat = "npc_wilderness", text = "The local wildlife is best admired from a safe distance." },
        { id = "exp2_npc_wilderness_014", cat = "npc_wilderness", text = "Keep your map close. The landmarks can look alike from here." },
        { id = "exp2_npc_wilderness_015", cat = "npc_wilderness", text = "May the road be kind to you." },
        { id = "v030_npc_relationships_001", cat = "npc_relationships", text = "You have been coming through here often. I hope the road has been kind to you." },
        { id = "v030_npc_relationships_003", cat = "npc_relationships", text = "The guild workers speak well of adventurers who treat them courteously." },
        { id = "v030_npc_relationships_005", cat = "npc_relationships", text = "I hope you and your friends have a safe journey." },
        { id = "v030_npc_relationships_007", cat = "npc_relationships", text = "People remember those who lend a hand when the road gets difficult." },
        { id = "v030_npc_relationships_009", cat = "npc_relationships", text = "Welcome back. It is good to see familiar travelers return safely." },
    },
