    squad = {
        lines = {
            { id = "squad_recruit_001", t = { "s.recruit" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "So I am on your roster now. Where do you want me?" },
            { id = "squad_recruit_002", t = { "s.recruit" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Name is {name}. I will follow your lead until you give me a reason not to." },
            { id = "squad_recruit_003", t = { "s.recruit" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "You picked me for this. I will try to be worth the slot." },
            { id = "squad_recruit_004", t = { "s.recruit" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Before we go: do you want me up front, in the back, or wherever the fight starts?" },
            { id = "squad_recruit_005", t = { "s.recruit" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "One rule from me: tell me when to hold and when to move. I will do the rest." },
            { id = "squad_recruit_006", t = { "s.recruit" }, roles = { "healer" }, races = {}, genders = {}, fam = {}, voices = {}, text = "I will keep you standing. Try to make that easy for me." },
            { id = "squad_recruit_007", t = { "s.recruit" }, roles = { "tank" }, races = {}, genders = {}, fam = {}, voices = {}, text = "Put me where the hits land. I will keep them off you." },
            { id = "squad_recruit_008", t = { "s.recruit" }, roles = { "damage" }, races = {}, genders = {}, fam = {}, voices = {}, text = "I hit what you mark. Nothing clever unless you ask." },
            { id = "squad_command_ack_001", t = { "s.ack_pull" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "On it." },
            { id = "squad_command_ack_002", t = { "s.ack_follow" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Following." },
            { id = "squad_command_ack_003", t = { "s.ack_hold" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Holding here." },
            { id = "squad_command_ack_004", t = { "s.ack_hold" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "I will stay put until you call." },
            { id = "squad_command_ack_005", t = { "s.ack_follow" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Understood. Regrouping." },
            { id = "squad_battle_call_002", t = { "s.battle" }, roles = { "tank" }, races = {}, genders = {}, fam = {}, voices = {}, text = "I have the first one. Let it come to me." },
            { id = "squad_battle_call_004", t = { "s.battle" }, roles = { "healer" }, races = {}, genders = {}, fam = {}, voices = {}, text = "Casting. Stay in range." },
            { id = "squad_battle_call_005", t = { "s.lowmp" }, roles = { "healer" }, races = {}, genders = {}, fam = {}, voices = {}, text = "I need a breath before the next pull." },
            { id = "squad_battle_call_006", t = { "s.battle" }, roles = { "damage" }, races = {}, genders = {}, fam = {}, voices = {}, text = "Ready when you are." },
            { id = "squad_battle_call_007", t = { "s.battle" }, roles = { "support" }, races = {}, genders = {}, fam = {}, voices = {}, text = "Buff is up. Say when you want the next." },
            { id = "squad_low_health_001", t = { "s.lowhp" }, roles = { "healer" }, races = {}, genders = {}, fam = {}, voices = {}, text = "I am low. Cover me for a moment." },
            { id = "squad_low_health_002", t = { "s.lowhp" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Taking a beating here. A cure would be welcome." },
            { id = "squad_low_health_003", t = { "s.lowhp" }, roles = { "tank" }, races = {}, genders = {}, fam = {}, voices = {}, text = "Armor is holding, but I could use a hand." },
            { id = "squad_after_battle_001", t = { "s.after" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "That went better than it had any right to." },
            { id = "squad_after_battle_002", t = { "s.after" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Check your supplies before we move." },
            { id = "squad_after_battle_003", t = { "s.after" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "If we keep pulling like that, we will run out of luck before we run out of targets." },
            { id = "squad_after_battle_004", t = { "s.after" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "I am fine. Check the others first." },
            { id = "squad_after_battle_005", t = { "s.after" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Good pace. I can keep this up for a while." },
            { id = "squad_member_down_001", t = { "s.down" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "I am down. Keep going without me." },
            { id = "squad_wipe_001", t = { "s.wipe" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "We lost that one. Regroup and talk it through." },
            { id = "squad_wipe_002", t = { "s.wipe" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "No shame in a retreat. I would rather try again than argue." },
            { id = "squad_wipe_003", t = { "s.wipe" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Take a minute. Then we go again." },
            { id = "squad_idle_town_001", t = { "s.idle_town" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "I will check the shops while you sort your gear." },
            { id = "squad_idle_town_002", t = { "s.idle_town" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "This city is louder than I remembered." },
            { id = "squad_idle_town_003", t = { "s.idle_town" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Do you need anything before we leave? I would rather ask now." },
            { id = "squad_idle_town_004", t = { "s.idle_town" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "If you are changing jobs, tell me. I will adjust." },
            { id = "squad_idle_town_005", t = { "s.idle_town" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "The guards keep looking at me. Probably the weapon." },
            { id = "squad_idle_town_006", t = { "s.idle_town" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "I will be at the gate when you are ready." },
            { id = "squad_idle_field_001", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Quiet out here. I prefer it that way." },
            { id = "squad_idle_field_002", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Want me to scout ahead a little?" },
            { id = "squad_idle_field_003", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Something moved over there. Probably nothing." },
            { id = "squad_idle_field_004", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Good ground here. We could rest if you need it." },
            { id = "squad_idle_field_005", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "I will keep watch while you check the map." },
            { id = "squad_idle_field_006", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Nothing on the horizon. That usually means something is hiding." },
            { id = "squad_banter_001", t = { "s.banter" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "You are standing in my light." },
            { id = "squad_banter_003", t = { "s.after" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Next time, warn me before you do that." },
            { id = "squad_banter_004", t = { "s.reply" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "You always say that, and then it works." },
            { id = "squad_banter_005", t = { "s.banter" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Keep your voice down. Something is listening." },
            { id = "squad_bond_001", t = { "s.bond" }, roles = {}, races = {}, genders = {}, fam = { "new" }, voices = {}, text = "I am still learning how you work. Give me time." },
            { id = "squad_bond_002", t = { "s.bond" }, roles = {}, races = {}, genders = {}, fam = { "new" }, voices = {}, text = "You do not have to explain everything. Just tell me what you need." },
            { id = "squad_bond_003", t = { "s.bond" }, roles = {}, races = {}, genders = {}, fam = { "steady" }, voices = {}, text = "You call, I move. That is how this works now." },
            { id = "squad_bond_004", t = { "s.bond" }, roles = {}, races = {}, genders = {}, fam = { "steady" }, voices = {}, text = "I have seen enough to know you will not waste us." },
            { id = "squad_bond_005", t = { "s.bond" }, roles = {}, races = {}, genders = {}, fam = { "trusted" }, voices = {}, text = "We have been through a lot together. I remember that." },
            { id = "squad_bond_006", t = { "s.bond" }, roles = {}, races = {}, genders = {}, fam = { "trusted" }, voices = {}, text = "Whatever we are walking into, I am with you." },
            { id = "squad_customization_002", t = { "s.jobchange" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "You changed jobs. I will adjust my place in the line." },
            { id = "squad_customization_004", t = { "s.jobchange_whm" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "If you are switching to healer, I am moving to the front." },
            { id = "squad_customization_005", t = { "s.jobchange" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Tell me the plan before you change your mind again." },
            { id = "squad_bench_001", t = { "s.bench" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Benched, not gone. Call me when you need me." },
            { id = "squad_bench_003", t = { "s.bench" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Take someone who fits the job. I will be here." },
            { id = "squad_bench_004", t = { "s.bench" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Do not apologize. It is a roster, not a verdict." },
            { id = "squad_bench_005", t = { "s.bench" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "I will be at the usual place. You know where to find me." },
            { id = "squad_reunion_001", t = { "s.reunion" }, roles = {}, races = {}, genders = {}, fam = { "trusted" }, voices = {}, text = "There you are. I was starting to think you found a better squad." },
            { id = "squad_reunion_002", t = { "s.reunion" }, roles = {}, races = {}, genders = {}, fam = { "trusted" }, voices = {}, text = "It has been a while. You look like you have stories." },
            { id = "squad_reunion_004", t = { "s.reunion" }, roles = {}, races = {}, genders = {}, fam = { "trusted" }, voices = {}, text = "Welcome back. Same formation as before?" },
            { id = "squad_flavor_race_001", t = { "s.race" }, roles = {}, races = { "Hume" }, genders = {}, fam = {}, voices = {}, text = "No grand destiny in my family. Just a road, a job, and a reason to keep walking." },
            { id = "squad_flavor_race_002", t = { "s.race" }, roles = {}, races = { "Hume" }, genders = {}, fam = {}, voices = {}, text = "Hume towns are all the same at night. One lamp, one argument, one open door." },
            { id = "squad_flavor_race_003", t = { "s.race" }, roles = {}, races = { "Elvaan" }, genders = {}, fam = {}, voices = {}, text = "San d'Oria taught me to stand straight. The road taught me to duck." },
            { id = "squad_flavor_race_004", t = { "s.race" }, roles = {}, races = { "Elvaan" }, genders = {}, fam = {}, voices = {}, text = "We are a proud people. It gets in the way of asking for directions." },
            { id = "squad_flavor_race_005", t = { "s.race" }, roles = {}, races = { "Tarutaru" }, genders = {}, fam = {}, voices = {}, text = "The grass is taller than I am out here. I can still see the road." },
            { id = "squad_flavor_race_006", t = { "s.race" }, roles = {}, races = { "Tarutaru" }, genders = {}, fam = {}, voices = {}, text = "Everyone pats my head in town. I have started charging for it." },
            { id = "squad_flavor_race_007", t = { "s.race" }, roles = {}, races = { "Mithra" }, genders = {}, fam = {}, voices = {}, text = "The wind carries smoke from the east. Probably someone's dinner, not trouble." },
            { id = "squad_flavor_race_008", t = { "s.race" }, roles = {}, races = { "Mithra" }, genders = {}, fam = {}, voices = {}, text = "People expect me to be quiet. I am quiet because I am listening." },
            { id = "squad_flavor_race_009", t = { "s.race" }, roles = {}, races = { "Galka" }, genders = {}, fam = {}, voices = {}, text = "Mind the doorway. I keep forgetting how low they build them." },
            { id = "squad_flavor_race_010", t = { "s.race" }, roles = {}, races = { "Galka" }, genders = {}, fam = {}, voices = {}, text = "I have been many places. None of them had a chair that fit." },
            { id = "squad_flavor_gender_001", t = { "s.gender" }, roles = {}, races = {}, genders = { "female" }, fam = {}, voices = {}, text = "I answer to {name}. 'Miss' is fine if you are being formal." },
            { id = "squad_flavor_gender_004", t = { "s.gender" }, roles = {}, races = {}, genders = { "male" }, fam = {}, voices = {}, text = "I answer to {name}. 'Sir' only if you are being formal." },
            { id = "fo_sq_pull_t1", t = { "s.battle" }, roles = { "tank" }, races = {}, genders = {}, fam = {}, voices = {}, text = "Eyes on me. I will hold it." },
            { id = "fo_sq_pull_t2", t = { "s.battle" }, roles = { "tank" }, races = {}, genders = {}, fam = {}, voices = {}, text = "Let it come to me first." },
