            { id = "fo_sq_town_c1", t = { "s.idle_town" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "calm" }, text = "A little peace is welcome. Take your time." },
            { id = "fo_sq_town_c2", t = { "s.idle_town" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "calm" }, text = "I will wait here. Do what you need to do." },
            { id = "fo_sq_town_c3", t = { "s.idle_town" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "calm" }, text = "It is good to rest somewhere safe." },
            { id = "fo_sq_town_ch1", t = { "s.idle_town" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "cheerful" }, text = "Ooh, so many people! I love town!" },
            { id = "fo_sq_town_ch2", t = { "s.idle_town" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "cheerful" }, text = "Can we get a snack before we go?" },
            { id = "fo_sq_town_ch3", t = { "s.idle_town" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "cheerful" }, text = "Shopping! Do we need anything? Can I look?" },
            { id = "fo_sq_town_g1", t = { "s.idle_town" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "gruff" }, text = "Hurry up. Towns make me itch." },
            { id = "fo_sq_town_g2", t = { "s.idle_town" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "gruff" }, text = "Let us get moving. Standing around is dull." },
            { id = "fo_sq_town_g3", t = { "s.idle_town" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "gruff" }, text = "Hmph. Waiting again." },
            { id = "fo_sq_field_01", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "I will watch our backs." },
            { id = "fo_sq_field_02", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Pick a target whenever you like." },
            { id = "fo_sq_field_03", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Mind your footing out here." },
            { id = "fo_sq_field_04", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Long way from town. Stay sharp." },
            { id = "fo_sq_field_05", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Do you want to keep hunting here, or move on?" },
            { id = "fo_sq_field_06", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "If you want to rest, now is a good time." },
            { id = "fo_sq_field_07", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Good thing you know the way. I would be lost." },
            { id = "fo_sq_field_08", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Watch for anything that sneaks up on us." },
            { id = "fo_sq_field_09", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "I like being out here with you." },
            { id = "fo_sq_field_10", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Let me know if you want to try somewhere else." },
            { id = "fo_sq_field_11", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Ready when you are. No rush." },
            { id = "fo_sq_field_12", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Keep your eyes open. This place is not as empty as it looks." },
            { id = "fo_sq_field_13", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "I will stay close." },
            { id = "fo_sq_field_14", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "The best part of a long road is the company." },
            { id = "fo_sq_field_15", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Remind me to mend my gear later." },
            { id = "fo_sq_field_16", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "We should not stray too far from the path." },
            { id = "fo_sq_field_h", t = { "s.idle_field" }, roles = { "healer" }, races = {}, genders = {}, fam = {}, voices = {}, text = "Stay near me out here. I cannot cure what I cannot reach." },
            { id = "fo_sq_field_t", t = { "s.idle_field" }, roles = { "tank" }, races = {}, genders = {}, fam = {}, voices = {}, text = "If anything charges us, I go first." },
            { id = "fo_sq_field_d", t = { "s.idle_field" }, roles = { "damage" }, races = {}, genders = {}, fam = {}, voices = {}, text = "I am itching for the next fight." },
            { id = "fo_sq_field_b1", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "bold" }, text = "Come on, let us find something worth fighting." },
            { id = "fo_sq_field_b2", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "bold" }, text = "I feel strong today. Let us push on." },
            { id = "fo_sq_field_b3", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "bold" }, text = "Nothing out here scares me. Well, almost nothing." },
            { id = "fo_sq_field_c1", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "calm" }, text = "It is peaceful out here, in its way." },
            { id = "fo_sq_field_c2", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "calm" }, text = "Let us keep a careful pace." },
            { id = "fo_sq_field_c3", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "calm" }, text = "I will keep watch. Rest your eyes a moment." },
            { id = "fo_sq_field_ch1", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "cheerful" }, text = "I love it out here!" },
            { id = "fo_sq_field_ch2", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "cheerful" }, text = "Ooh, I wonder what is up ahead!" },
            { id = "fo_sq_field_ch3", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "cheerful" }, text = "This is the best part. The walking and the talking!" },
            { id = "fo_sq_field_g1", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "gruff" }, text = "Standing around will not make us any stronger." },
            { id = "fo_sq_field_g2", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "gruff" }, text = "Pick something and hit it already." },
            { id = "fo_sq_field_g3", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "gruff" }, text = "Hmph. Too quiet." },
            { id = "fo_sq_banter_01", t = { "s.banter" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Whose turn is it to carry the food?" },
            { id = "fo_sq_banter_02", t = { "s.banter" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Do not stand so close. I need room to swing." },
            { id = "fo_sq_banter_03", t = { "s.banter" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Someone keeps humming. It is not me." },
            { id = "fo_sq_banter_04", t = { "s.banter" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "If anyone sees a treasure chest, it is mine." },
            { id = "fo_sq_banter_05", t = { "s.banter" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "I bet I land the last hit next fight." },
            { id = "fo_sq_banter_06", t = { "s.banter" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Try to keep up, everyone." },
            { id = "fo_sq_banter_07", t = { "s.banter" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Remind me again why I agreed to this." },
            { id = "fo_sq_banter_08", t = { "s.banter" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Quiet, all of you. I am listening." },
            { id = "fo_sq_banter_b", t = { "s.banter" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "bold" }, text = "Next fight, I go first. No arguments." },
            { id = "fo_sq_banter_c", t = { "s.banter" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "calm" }, text = "Save your strength for the monsters, everyone." },
            { id = "fo_sq_banter_ch", t = { "s.banter" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "cheerful" }, text = "We make a great team, do we not?" },
            { id = "fo_sq_banter_g", t = { "s.banter" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "gruff" }, text = "Less talking, more walking." },
            { id = "fo_sq_down_1", t = { "s.down" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "I cannot... keep up..." },
            { id = "fo_sq_down_2", t = { "s.down" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Finish it... for me..." },
            { id = "fo_sq_down_3", t = { "s.down" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Do not stop... for me..." },
            { id = "fo_sq_down_b1", t = { "s.down" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "bold" }, text = "I fall... but you will win this..." },
            { id = "fo_sq_down_b2", t = { "s.down" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "bold" }, text = "Keep fighting... do not look back..." },
            { id = "fo_sq_down_c1", t = { "s.down" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "calm" }, text = "I am sorry... I am out of this one..." },
            { id = "fo_sq_down_c2", t = { "s.down" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "calm" }, text = "Stay safe... without me..." },
            { id = "fo_sq_down_ch1", t = { "s.down" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "cheerful" }, text = "Oof... down I go..." },
            { id = "fo_sq_down_ch2", t = { "s.down" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "cheerful" }, text = "I will just... lie here a bit..." },
            { id = "fo_sq_down_g1", t = { "s.down" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "gruff" }, text = "Bah... finish it..." },
            { id = "fo_sq_down_g2", t = { "s.down" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "gruff" }, text = "Tch... do not lose this..." },
            { id = "fo_sq_wipe_1", t = { "s.wipe" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Back on your feet? Good. We try again." },
            { id = "fo_sq_wipe_2", t = { "s.wipe" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "We go again, more carefully this time." },
            { id = "fo_sq_wipe_3", t = { "s.wipe" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "That one got the better of us. Not again." },
            { id = "fo_sq_wipe_b1", t = { "s.wipe" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "bold" }, text = "We fell, so we rise. Let us go!" },
            { id = "fo_sq_wipe_b2", t = { "s.wipe" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "bold" }, text = "Round two. This time we win." },
            { id = "fo_sq_wipe_c1", t = { "s.wipe" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "calm" }, text = "Let us slow down this time. One fight at a time." },
            { id = "fo_sq_wipe_c2", t = { "s.wipe" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "calm" }, text = "Are you all right? Take your time." },
            { id = "fo_sq_wipe_ch1", t = { "s.wipe" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "cheerful" }, text = "Okay! Fresh start!" },
            { id = "fo_sq_wipe_ch2", t = { "s.wipe" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "cheerful" }, text = "We got knocked down. We get back up!" },
            { id = "fo_sq_wipe_g1", t = { "s.wipe" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "gruff" }, text = "Hmph. Try not to fall this time." },
            { id = "fo_sq_wipe_g2", t = { "s.wipe" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "gruff" }, text = "Again. And watch your back." },
            { id = "fo_sq_hold_1", t = { "s.ack_hold" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "I will hold this spot." },
            { id = "fo_sq_hold_2", t = { "s.ack_hold" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Staying right here." },
            { id = "fo_sq_hold_3", t = { "s.ack_hold" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Holding. Call me when you need me." },
            { id = "fo_sq_hold_b", t = { "s.ack_hold" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "bold" }, text = "This ground is ours. Holding!" },
            { id = "fo_sq_hold_c", t = { "s.ack_hold" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "calm" }, text = "I will wait here." },
            { id = "fo_sq_hold_ch", t = { "s.ack_hold" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "cheerful" }, text = "Okay! I will wait right here!" },
            { id = "fo_sq_hold_g", t = { "s.ack_hold" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "gruff" }, text = "Fine. Not moving." },
            { id = "fo_sq_follow_1", t = { "s.ack_follow" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "On my way." },
            { id = "fo_sq_follow_2", t = { "s.ack_follow" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Coming." },
            { id = "fo_sq_follow_3", t = { "s.ack_follow" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "With you." },
            { id = "fo_sq_follow_b", t = { "s.ack_follow" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "bold" }, text = "Lead on!" },
            { id = "fo_sq_follow_c", t = { "s.ack_follow" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "calm" }, text = "I will follow your lead." },
            { id = "fo_sq_follow_ch", t = { "s.ack_follow" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "cheerful" }, text = "Wait for me!" },
            { id = "fo_sq_follow_g", t = { "s.ack_follow" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "gruff" }, text = "Yeah, yeah. Coming." },
            { id = "fo_sq_bond_n1", t = { "s.bond" }, roles = {}, races = {}, genders = {}, fam = { "new" }, voices = {}, text = "I do not know you well yet. I will learn." },
            { id = "fo_sq_bond_n2", t = { "s.bond" }, roles = {}, races = {}, genders = {}, fam = { "new" }, voices = {}, text = "Tell me how you like to fight. I will adapt." },
            { id = "fo_sq_bond_n3", t = { "s.bond" }, roles = {}, races = {}, genders = {}, fam = { "new" }, voices = {}, text = "Still finding my footing with you." },
            { id = "fo_sq_bond_n4", t = { "s.bond" }, roles = {}, races = {}, genders = {}, fam = { "new" }, voices = {}, text = "I will try not to get in your way." },
            { id = "fo_sq_bond_s1", t = { "s.bond" }, roles = {}, races = {}, genders = {}, fam = { "steady" }, voices = {}, text = "We are getting good at this." },
            { id = "fo_sq_bond_s2", t = { "s.bond" }, roles = {}, races = {}, genders = {}, fam = { "steady" }, voices = {}, text = "I know your timing now. It helps." },
            { id = "fo_sq_bond_s3", t = { "s.bond" }, roles = {}, races = {}, genders = {}, fam = { "steady" }, voices = {}, text = "Same as always? Good." },
            { id = "fo_sq_bond_s4", t = { "s.bond" }, roles = {}, races = {}, genders = {}, fam = { "steady" }, voices = {}, text = "You can count on me. You know that by now." },
            { id = "fo_sq_bond_t1", t = { "s.bond" }, roles = {}, races = {}, genders = {}, fam = { "trusted" }, voices = {}, text = "I would follow you into any fight." },
            { id = "fo_sq_bond_t2", t = { "s.bond" }, roles = {}, races = {}, genders = {}, fam = { "trusted" }, voices = {}, text = "There is nobody I would rather fight beside." },
            { id = "fo_sq_bond_t3", t = { "s.bond" }, roles = {}, races = {}, genders = {}, fam = { "trusted" }, voices = {}, text = "I am glad you keep calling on me." },
            { id = "fo_sq_bond_t4", t = { "s.bond" }, roles = {}, races = {}, genders = {}, fam = { "trusted" }, voices = {}, text = "Whatever comes, we handle it together." },
            { id = "fo_sq_back_1", t = { "s.reunion" }, roles = {}, races = {}, genders = {}, fam = { "trusted" }, voices = {}, text = "Back again. I kept my gear ready." },
            { id = "fo_sq_back_2", t = { "s.reunion" }, roles = {}, races = {}, genders = {}, fam = { "trusted" }, voices = {}, text = "It has been a few days. Good to see you." },
            { id = "fo_sq_back_3", t = { "s.reunion" }, roles = {}, races = {}, genders = {}, fam = { "trusted" }, voices = {}, text = "I wondered when you would call." },
            { id = "fo_sq_back_b", t = { "s.reunion" }, roles = {}, races = {}, genders = {}, fam = { "trusted" }, voices = { "bold" }, text = "At last! I was getting restless." },
            { id = "fo_sq_back_c", t = { "s.reunion" }, roles = {}, races = {}, genders = {}, fam = { "trusted" }, voices = { "calm" }, text = "Welcome back. I hope you rested well." },
            { id = "fo_sq_back_ch", t = { "s.reunion" }, roles = {}, races = {}, genders = {}, fam = { "trusted" }, voices = { "cheerful" }, text = "You are back! I missed this!" },
            { id = "fo_sq_back_g", t = { "s.reunion" }, roles = {}, races = {}, genders = {}, fam = { "trusted" }, voices = { "gruff" }, text = "Took you long enough." },
            { id = "fo_sq_job_1", t = { "s.jobchange" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "New job? I will watch how you fight now." },
            { id = "fo_sq_job_2", t = { "s.jobchange" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Different job, same plan. I am with you." },
            { id = "fo_sq_job_3", t = { "s.jobchange" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "Changed jobs again? I will keep up." },
            { id = "fo_sq_job_b", t = { "s.jobchange" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "bold" }, text = "A change of job! Let us test it in a real fight." },
            { id = "fo_sq_job_c", t = { "s.jobchange" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "calm" }, text = "A change of job. I will adjust to you." },
            { id = "fo_sq_job_ch", t = { "s.jobchange" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "cheerful" }, text = "Ooh, a different job! Show me what it can do!" },
            { id = "fo_sq_job_g", t = { "s.jobchange" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "gruff" }, text = "Another job. Hmph. Just do not get us killed learning it." },
            { id = "fo_sq_job_whm1", t = { "s.jobchange_whm" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "You are healing now? Then I will try not to need it." },
            { id = "fo_sq_job_whm2", t = { "s.jobchange_whm" }, roles = {}, races = {}, genders = {}, fam = {}, voices = {}, text = "A healer. Good. I will keep them off you." },
            { id = "fo_sq_bench_b", t = { "s.bench" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "bold" }, text = "Rest is wasted on me, but very well." },
            { id = "fo_sq_bench_c", t = { "s.bench" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "calm" }, text = "I understand. Good luck out there." },
            { id = "fo_sq_bench_ch", t = { "s.bench" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "cheerful" }, text = "Aww. Okay! Call me soon!" },
            { id = "fo_sq_bench_g", t = { "s.bench" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "gruff" }, text = "Hmph. Fine." },
            { id = "fo_sq_race_hu1", t = { "s.race" }, roles = {}, races = { "Hume" }, genders = {}, fam = {}, voices = {}, text = "Humes get along with almost anyone. It is our one great talent." },
            { id = "fo_sq_race_hu2", t = { "s.race" }, roles = {}, races = { "Hume" }, genders = {}, fam = {}, voices = {}, text = "My grandmother said Humes were made for walking. She was right." },
            { id = "fo_sq_race_el1", t = { "s.race" }, roles = {}, races = { "Elvaan" }, genders = {}, fam = {}, voices = {}, text = "An Elvaan keeps their word. I keep mine." },
            { id = "fo_sq_race_el2", t = { "s.race" }, roles = {}, races = { "Elvaan" }, genders = {}, fam = {}, voices = {}, text = "We Elvaan do not slouch. Not even when we are tired." },
            { id = "fo_sq_race_ta1", t = { "s.race" }, roles = {}, races = { "Tarutaru" }, genders = {}, fam = {}, voices = {}, text = "Being small has its uses. Monsters often look right past me." },
            { id = "fo_sq_race_ta2", t = { "s.race" }, roles = {}, races = { "Tarutaru" }, genders = {}, fam = {}, voices = {}, text = "Windurst taught me patience. The road is teaching me the rest." },
            { id = "fo_sq_race_mi1", t = { "s.race" }, roles = {}, races = { "Mithra" }, genders = {}, fam = {}, voices = {}, text = "My nose has never lied to me. Neither have my ears." },
            { id = "fo_sq_race_mi2", t = { "s.race" }, roles = {}, races = { "Mithra" }, genders = {}, fam = {}, voices = {}, text = "Windurst is home now, but I still dream of the southern seas." },
            { id = "fo_sq_race_ga1", t = { "s.race" }, roles = {}, races = { "Galka" }, genders = {}, fam = {}, voices = {}, text = "Galka do not remember being young. We remember almost everything else." },
            { id = "fo_sq_race_ga2", t = { "s.race" }, roles = {}, races = { "Galka" }, genders = {}, fam = {}, voices = {}, text = "People think Galka are slow. We are just careful." },
            { id = "fo_sq_jo1_b_pull", t = { "s.battle" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "bold" }, text = "Hope everyone is awake. I am bringing company." },
            { id = "fo_sq_jo1_b_lowhp", t = { "s.lowhp" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "bold" }, text = "I have walked away from worse." },
            { id = "fo_sq_jo1_b_after", t = { "s.after" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "bold" }, text = "Now that is how you earn your gil." },
            { id = "fo_sq_jo1_b_town", t = { "s.idle_town" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "bold" }, text = "Enough sightseeing. Let us find some trouble." },
            { id = "fo_sq_jo1_b_field", t = { "s.idle_field" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "bold" }, text = "I wonder what is waiting beyond that hill." },
            { id = "fo_sq_jo1_c_pull", t = { "s.battle" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "calm" }, text = "Ready yourselves. One at a time." },
            { id = "fo_sq_jo1_c_lowhp", t = { "s.lowhp" }, roles = {}, races = {}, genders = {}, fam = {}, voices = { "calm" }, text = "A little healing would be appreciated." },
